(function(){
function Panzoom(el, opts = {}) {
  let state = { x: 0, y: 0, scale: 1 };
  const min = opts.minScale ?? 1;
  const max = opts.maxScale ?? 4;
  const pointers = new Map();
  let drag = null;
  let pinchStart = null;

  const apply = () => {
    if (opts.setTransform) opts.setTransform(el, state);
    else el.style.transform = `translate(${state.x}px, ${state.y}px) scale(${state.scale})`;
  };

  const clampScale = (s) => Math.min(max, Math.max(min, s));
  const dist = (a,b) => Math.hypot(a.clientX - b.clientX, a.clientY - b.clientY);

  el.style.touchAction = 'none';

  el.addEventListener('pointerdown', (e) => {
    pointers.set(e.pointerId, e);
    el.setPointerCapture(e.pointerId);
    if (pointers.size === 1) drag = { dx: e.clientX - state.x, dy: e.clientY - state.y };
    if (pointers.size === 2) {
      const [p1, p2] = [...pointers.values()];
      pinchStart = { distance: dist(p1, p2), scale: state.scale };
      drag = null;
    }
  });

  el.addEventListener('pointermove', (e) => {
    if (!pointers.has(e.pointerId)) return;
    pointers.set(e.pointerId, e);

    if (pointers.size === 2 && pinchStart) {
      const [p1, p2] = [...pointers.values()];
      state.scale = clampScale(pinchStart.scale * (dist(p1, p2) / pinchStart.distance));
      apply();
      return;
    }

    if (drag && pointers.size === 1) {
      state.x = e.clientX - drag.dx;
      state.y = e.clientY - drag.dy;
      apply();
    }
  });

  const onUp = (e) => {
    pointers.delete(e.pointerId);
    if (pointers.size < 2) pinchStart = null;
    if (pointers.size === 1) {
      const p = [...pointers.values()][0];
      drag = { dx: p.clientX - state.x, dy: p.clientY - state.y };
    }
    if (pointers.size === 0) drag = null;
  };
  el.addEventListener('pointerup', onUp);
  el.addEventListener('pointercancel', onUp);

  function zoomWithWheel(e) {
    e.preventDefault();
    const delta = e.deltaY < 0 ? 1.08 : 0.92;
    state.scale = clampScale(state.scale * delta);
    apply();
  }

  apply();
  return { zoomWithWheel, reset(){ state = { x: 0, y: 0, scale: 1 }; apply(); }, getScale(){ return state.scale; } };
}
window.Panzoom = Panzoom;
})();
